begin;
select no_plan();
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
insert into cooksmith.household_recipes(id,household_id,name) values('a0000000-0000-4000-8000-000000000079','20000000-0000-4000-8000-000000000001','Synthetic precision recipe');
insert into cooksmith.planned_meals(id,household_id,meal_date,meal_type,title,recipe_id) values('80000000-0000-4000-8000-000000000079','20000000-0000-4000-8000-000000000001','2026-11-22','dinner','Synthetic precision meal','a0000000-0000-4000-8000-000000000079');
-- These are the client contract payloads, not proof of browser/API execution.
select cooksmith.reconcile_planned_meal_shopping('20000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000079','[{"name":"saffron","quantity":null,"unit":"g","category":"pantry","sourceQuantities":[{"name":"saffron","quantity":"0.004","unit":"g","originalText":"0.004 g saffron"}]}]');
select is((select quantity from cooksmith.shopping_list_items where display_name='saffron'),null::numeric,'Unrepresentable demand remains unknown, never stored zero');
select is((select source_quantities->0->>'quantity' from cooksmith.shopping_item_contributions where planned_meal_id='80000000-0000-4000-8000-000000000079'),'0.004','Original precise source survives numeric row storage');
create temporary table precision_ids as select id, shopping_item_id from cooksmith.shopping_item_contributions where planned_meal_id='80000000-0000-4000-8000-000000000079';
select cooksmith.reconcile_planned_meal_shopping('20000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000079','[{"name":"saffron","quantity":null,"unit":"g","category":"pantry","sourceQuantities":[{"name":"saffron","quantity":"0.004","unit":"g","originalText":"0.004 g saffron"}]}]');
select results_eq('select id, shopping_item_id from cooksmith.shopping_item_contributions where planned_meal_id=''80000000-0000-4000-8000-000000000079''','select id, shopping_item_id from precision_ids','Retry preserves source and item identities');
select cooksmith.record_shopping_stock_purchase('20000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000079','saffron',(select jsonb_agg(jsonb_build_object('id',id,'updatedAt',updated_at)) from cooksmith.shopping_list_items where display_name='saffron'),'[{"quantity":0.004,"unit":"g"}]');
select is((select amounts->0->>'quantity' from cooksmith.shopping_stock_purchases where id='90000000-0000-4000-8000-000000000079'),'0.004','Receipt JSON snapshots precise bought quantity without numeric column coercion');
select ok((select source_quantities::text like '%0.004%' from cooksmith.shopping_stock_purchases where id='90000000-0000-4000-8000-000000000079'),'Receipt retains original source evidence');
select cooksmith.unbuy_shopping_stock('20000000-0000-4000-8000-000000000001',(select array_agg(id) from cooksmith.shopping_list_items where display_name='saffron'));
select ok((select voided_at is not null from cooksmith.shopping_stock_purchases where id='90000000-0000-4000-8000-000000000079'),'Undo preserves and voids receipt instead of deleting evidence');
select is((select quantity from cooksmith.shopping_list_items where display_name='saffron'),null::numeric,'Undo does not invent a rounded quantity');
insert into cooksmith.shopping_list_items(household_id,display_name,quantity,unit,category) values('20000000-0000-4000-8000-000000000001','Synthetic exact mass',4,'g','pantry'),('20000000-0000-4000-8000-000000000001','Synthetic exact volume',4,'ml','pantry');
select is((select quantity from cooksmith.shopping_list_items where display_name='Synthetic exact mass'),4::numeric,'Normalised 0.004 kg reads back as 4 g');
select is((select unit from cooksmith.shopping_list_items where display_name='Synthetic exact volume'),'ml','Normalised volume unit persists');
select cooksmith.update_shopping_purchase('20000000-0000-4000-8000-000000000001',(select jsonb_agg(jsonb_build_object('id',id,'name',display_name,'quantity',0.25,'unit','g','category','pantry','measurementSystem','unknown')) from cooksmith.shopping_list_items where display_name='saffron'));
select cooksmith.reconcile_planned_meal_shopping('20000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000079','[{"name":"saffron","quantity":null,"unit":"g","category":"pantry","sourceQuantities":[{"name":"saffron","quantity":"0.004","unit":"g"}]}]');
select is((select quantity from cooksmith.shopping_list_items where display_name='saffron'),0.25::numeric,'Regeneration preserves deliberate override');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000003',true);
select is((select count(*) from cooksmith.shopping_list_items where display_name='Synthetic exact mass'),0::bigint,'Other household cannot read the amount');
select throws_ok($$select cooksmith.reconcile_planned_meal_shopping('20000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000079','[]')$$,'42501',null,'Other household cannot reconcile precise sources');
select * from finish();
rollback;
